package com.nexttv;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;
/** Public UI only: select a real past EPG programme and verify the minified Release timeline. */
public class ReplayMenuReleaseInstrumentation extends ViewingDesignInstrumentation {
 AccessibilityNodeInfo slider(){AccessibilityNodeInfo n=FreshAccessibilityNodes.focused(root());return n!=null&&n.getRangeInfo()!=null?n:null;}
 float value(){AccessibilityNodeInfo n=slider();if(n==null)throw new IllegalStateException("Timeline lost focus "+focus());return n.getRangeInfo().getCurrent();}
 @Override public void onStart(){int code=Activity.RESULT_OK;String result="";try{
  prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=prefs.getAll();prefs.edit().putBoolean("start_live",false).putBoolean("auto_update",false).putBoolean("auto_update_epg",false).putInt("preload_mode",0).commit();
  activity=startActivitySync(new Intent().setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await("home",()->focus().equals("频道"));click("CCTV1综合");rendered();key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_DPAD_CENTER);await("browser",()->browser().optString("region").equals("channels"));key(KeyEvent.KEYCODE_DPAD_RIGHT);await("EPG",()->browser().optString("region").equals("epg"));
  int attempts=0;do{key(KeyEvent.KEYCODE_DPAD_UP);}while(!focus().contains("回放")&&++attempts<12);if(!focus().contains("回放"))throw new IllegalStateException("No real replay programme in EPG: "+focus());key(KeyEvent.KEYCODE_DPAD_CENTER);await("replay information",()->text().contains("回放中"));rendered();key(KeyEvent.KEYCODE_MENU);await("replay controls",()->text().contains("返回直播")&&focus().contains("暂停"));key(KeyEvent.KEYCODE_DPAD_CENTER);await("paused",()->focus().contains("继续播放"));shot("release-replay-normal");
  key(KeyEvent.KEYCODE_DPAD_UP);await("timeline focus",()->slider()!=null);float before=value();key(KeyEvent.KEYCODE_DPAD_UP);if(Math.abs(value()-before)>.002f)throw new IllegalStateException("Up changed replay position");key(KeyEvent.KEYCODE_DPAD_DOWN);await("return pause action",()->focus().contains("继续播放"));pass("real past EPG selection opens replay; Up enters timeline and does not seek; Down restores the action");
  key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_RIGHT);await("audio",()->focus().equals("音轨"));key(KeyEvent.KEYCODE_DPAD_UP);await("timeline from audio",()->slider()!=null);key(KeyEvent.KEYCODE_DPAD_DOWN);await("exact audio restore",()->focus().equals("音轨"));key(KeyEvent.KEYCODE_DPAD_UP);before=value();key(KeyEvent.KEYCODE_DPAD_RIGHT);if(value()<=before)throw new IllegalStateException("Right did not seek forward");key(KeyEvent.KEYCODE_DPAD_LEFT);if(Math.abs(value()-before)>.01f)throw new IllegalStateException("Left did not rewind");shot("release-replay-focused");pass("timeline retains original thin style and supports directional seeking with exact action restoration");
  Rect b=new Rect();slider().getBoundsInScreen(b);long time=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_MOVE,MotionEvent.ACTION_UP}){float fraction=action==MotionEvent.ACTION_DOWN?.3f:.6f;MotionEvent event=MotionEvent.obtain(time,SystemClock.uptimeMillis(),action,b.left+b.width()*fraction,b.top-5,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);if(!getUiAutomation().injectInputEvent(event,true))throw new IllegalStateException("Touch injection rejected");event.recycle();SystemClock.sleep(100);}await("touch seeks within invisible hit band",()->slider()!=null&&value()>.5f&&value()<.7f);key(KeyEvent.KEYCODE_DPAD_DOWN);await("keyboard returns after touch",()->focus().equals("音轨"));key(KeyEvent.KEYCODE_ESCAPE);await("all controls close",()->!text().contains("解码方式"));pass("touch outside the visual thin line drags replay and hands control back to keyboard in actual Release");key(KeyEvent.KEYCODE_INFO);await("replay information only",()->find("CCTV1综合",root())!=null&&!text().contains("解码方式"));shot("release-replay-info");result="Release replay timeline: "+passed+" groups passed";
 }catch(Throwable t){code=Activity.RESULT_CANCELED;result=android.util.Log.getStackTraceString(t);}finally{restore();}Bundle b=new Bundle();b.putString("stream",result);finish(code,b);
 }
}
